tool_input.command:
python3 - <<'EOF'
p='src/app/utils/householdDashboard.ts'
s=open(p).read()
old_identity='''const entryIdentity = (entry: Record<string, any>) =>
  entry.importSource?.key || (entry.id ? `manual:${entry.id}` : "");'''
new_identity='''// 저장 서비스의 householdIdentity와 같은 값. 위치를 찾는 데 쓰지 않고, 같은 위치의 추가 확인에만 쓴다.
const entryIdentity = (entry: Record<string, any>) =>
  entry.importSource?.key || `manual:${entry.id}`;'''
assert old_identity in s
s=s.replace(old_identity,new_identity)
old='''  const shapes = householdRecords.map((record) => householdRecordShape(record));
  // 같은 식별키가 여러 거래에 있으면 어느 거래를 고칠지 모호하므로 편집을 막는다.
  const identityCounts = new Map<string, number>();
  for (const shape of shapes)
    if (shape.kind === "array")
      for (const entry of shape.raw)
        if (entry && typeof entry === "object") {
          const identity = entryIdentity(entry as Record<string, any>);
          if (identity)
            identityCounts.set(identity, (identityCounts.get(identity) || 0) + 1);
        }
'''
new='''  const shapes = householdRecords.map((record) => householdRecordShape(record));
'''
assert old in s
s=s.replace(old,new)
old='''      const identity = legacy ? `legacy:${recordId}` : entryIdentity(entry);
      const editBlock = !recordId
        ? "기록 위치를 확인할 수 없어 편집할 수 없습니다."
        : shape.kind === "corrupt"
          ? "저장된 거래 목록을 읽을 수 없어 편집하지 않습니다. 원본은 그대로 둡니다."
          : !legacy && !entry.id
            ? "식별 정보가 없는 예전 거래라 편집할 수 없습니다."
            : !legacy && (identityCounts.get(identity) || 0) > 1
              ? "같은 식별 정보의 거래가 여러 건이라 어느 거래인지 모호합니다. 편집하지 않습니다."
              : undefined;'''
new='''      // 거래 id가 없거나 같은 id가 여러 건이어도 기록 위치(recordId + rawIndex)와 원본 지문으로 구분한다.
      const identity = legacy ? `legacy:${recordId}` : entryIdentity(entry);
      const editBlock = !recordId
        ? "기록 위치를 확인할 수 없어 편집할 수 없습니다."
        : shape.kind === "corrupt"
          ? "저장된 거래 목록을 읽을 수 없어 편집하지 않습니다. 원본은 그대로 둡니다."
          : undefined;'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)

p='src/app/services/householdEditService.ts'
s=open(p).read()
old='''        const current = before[locator.rawIndex];
        if (!current || typeof current !== 'object' || !(current as HouseholdEntry).id) throw new HouseholdEditConflict();
        const identity = householdIdentity(current as HouseholdEntry);
        if (identity !== locator.identity
          || before.filter(entry => entry && typeof entry === 'object' && householdIdentity(entry as HouseholdEntry) === identity).length !== 1) {
          throw new HouseholdEditConflict();
        }'''
new='''        // 위치는 recordId + rawIndex로만 정한다. 같은 id·식별키가 다른 위치에 있어도 그 위치를 찾지 않는다.
        // identity는 같은 위치의 추가 확인이며, 거래의 id·importSource는 만들거나 바꾸지 않는다.
        const current = before[locator.rawIndex];
        if (!current || typeof current !== 'object' || householdIdentity(current as HouseholdEntry) !== locator.identity) throw new HouseholdEditConflict();'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF

sed -i '' 's/^function loadHouseholdPage(records, tab = "transactions", chartState = {}) {$/function loadHouseholdPage(records, tab = "transactions", chartState = {}, user = { uid: "fixture" }) {/; s/^      useAuth: () => ({ user: { uid: "fixture" } }),$/      useAuth: () => ({ user }),/' test/householdSummary.test.mjs && grep -n 'function loadHouseholdPage\|useAuth: () =>' test/householdSummary.test.mjs && cat >> test/householdSummary.test.mjs <<'EOF'

test("로그아웃·계정 전환 첫 화면은 빈 편집·선택 상태에 접근하지 않고 이전 계정 거래를 숨긴다", () => {
  const records = [{ id: "2026-10-01_household", date: `${month}-05`, household_entries: JSON.stringify([entry({ memo: "이전 계정 메모" })]) }];
  // 로그아웃(user=null): uid와 편집·선택 상태가 모두 비어 있어도 null.entry/null.entries에 접근하지 않는다.
  const signedOut = renderToStaticMarkup(React.createElement(loadHouseholdPage(records, "transactions", {}, null)));
  assert.match(signedOut, /로그인 후 내 가계부를 확인할 수 있습니다/);
  assert.doesNotMatch(signedOut, /이전 계정 메모/);
  // 다른 계정으로 바뀐 첫 프레임: 불러온 거래의 소유 계정(fixture)과 달라 표시하지 않는다.
  const switched = renderToStaticMarkup(React.createElement(loadHouseholdPage(records, "transactions", {}, { uid: "other" })));
  assert.doesNotMatch(switched, /이전 계정 메모/);
});
EOF

cat >> test/householdCashEntry.test.mjs <<'EOF'

test('저장 중 상태 확인용 mounted 값은 effect setup에서 다시 true가 되어 StrictMode 재실행 뒤에도 저장 결과를 받는다', () => {
  for (const file of ['HouseholdCashEntry.tsx', 'HouseholdEditSheet.tsx', 'HouseholdCategoryManager.tsx']) {
    const source = readFileSync(new URL(`../src/app/components/${file}`, import.meta.url), 'utf8');
    assert.match(source, /useEffect\(\(\) => \{ mounted\.current = true; return \(\) => \{ mounted\.current = false; \}; \}, \[\]\);/, file);
    assert.doesNotMatch(source, /useEffect\(\(\) => \(\) => \{ mounted\.current = false; \}, \[\]\)/, file);
  }
});

test('분류 관리는 연 계정에만 그리고 계정별 key로 내부 입력을 나누며, 늦은 설정 조회는 최신 변경을 덮지 않는다', () => {
  const page = readFileSync(new URL('../src/app/pages/HouseholdPage.tsx', import.meta.url), 'utf8');
  assert.match(page, /\{uid && managerOwner === uid && \([\s\S]{0,120}<HouseholdCategoryManager\s+key=\{uid\}/);
  // 변경 결과 반영 시 수정 번호를 올리고, 조회는 시작 때 번호와 다르면 그 항목을 덮지 않는다.
  assert.match(page, /if \(patch\.categories\) settingsRevision\.current\.categories\+\+;/);
  assert.match(page, /if \(patch\.rules\) settingsRevision\.current\.rules\+\+;/);
  assert.match(page, /const started = \{ \.\.\.settingsRevision\.current \};/);
  assert.match(page, /keepRules\s*\? own!\.rules/);
  // 현금 재시도가 이미 저장됨이고 첫 시도와 분류가 다를 수 있으면 거래처 기억을 저장하지 않는다.
  assert.match(page, /result\.already && saved\.rememberMismatch\)[\s\S]{0,400}return;/);
});
EOF
